"""LeadHunter Dashboard v4.2 — locked presentation + verified API wiring."""
DASHBOARD_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>LeadHunter</title><style>
:root{--bg:#f4f6f8;--card:#fff;--ink:#18212f;--muted:#687386;--line:#e2e7ed;--accent:#16a34a;--blue:#2563eb;--warn:#d97706;--danger:#dc2626;--r:18px;--shadow:0 10px 30px #18212f12}
*{box-sizing:border-box}body{margin:0;font:14px Inter,system-ui,sans-serif;background:var(--bg);color:var(--ink)}body.dark{--bg:#0b1118;--card:#121b26;--ink:#eef3f8;--muted:#9aa7b6;--line:#263342;--shadow:0 12px 32px #0005}body.neo{--r:5px;--shadow:6px 6px 0 #18212f22}body.neo.dark{--shadow:6px 6px 0 #000}
.app{max-width:1440px;margin:auto;padding:16px 24px 90px}.top{display:flex;justify-content:space-between;align-items:center;gap:14px}.brand{display:flex;align-items:center;gap:11px}.logo{width:44px;height:44px;display:grid;place-items:center;background:var(--accent);border-radius:13px;font-size:21px}.brand b{letter-spacing:.12em}.sub,.muted{color:var(--muted);font-size:12px}.tools,.actions,.themepick{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:var(--card);color:var(--ink);padding:10px 13px;border-radius:11px;cursor:pointer}.btn.primary{background:var(--accent);color:white;border-color:var(--accent);font-weight:700}.btn.small{padding:7px 10px;font-size:12px}.nav{display:flex;gap:5px;margin-top:16px;padding:7px;background:var(--card);border:1px solid var(--line);border-radius:15px;box-shadow:var(--shadow);overflow:auto}.nav button{border:0;background:transparent;color:var(--muted);padding:11px 15px;border-radius:10px;cursor:pointer;white-space:nowrap}.nav button.active{background:var(--accent);color:white;font-weight:700}.page{display:none;padding-top:28px}.page.active{display:block}.eyebrow{font-size:11px;color:var(--accent);font-weight:800;letter-spacing:.15em}.title{font-size:30px;margin:6px 0}.lead{color:var(--muted);line-height:1.6;max-width:760px}.grid{display:grid;gap:16px}.metrics{grid-template-columns:repeat(4,1fr);margin:22px 0}.split{grid-template-columns:1.15fr .85fr}.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:18px;box-shadow:var(--shadow)}.metric strong{display:block;font-size:29px;margin-top:8px}.list{display:grid;gap:10px}.item{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px}.row{display:flex;justify-content:space-between;align-items:center;gap:12px}.form{display:grid;grid-template-columns:1fr 1fr 140px auto;gap:12px}.field label{display:block;font-size:12px;color:var(--muted);margin-bottom:6px}.field select{width:100%;padding:12px;border:1px solid var(--line);border-radius:11px;background:var(--card);color:var(--ink)}.dataset{cursor:pointer}.dataset:hover{border-color:var(--accent)}.dataset.selected{outline:2px solid var(--accent)}.tag{display:inline-block;padding:5px 9px;border-radius:999px;background:#16a34a18;color:var(--accent);font-size:11px;font-weight:700;margin:3px}.leadcard{padding:0;overflow:hidden}.leadhead{padding:14px 16px;cursor:pointer}.details{display:none;border-top:1px solid var(--line);padding:16px}.leadcard.open .details{display:block}.detailgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.kv{border:1px solid var(--line);padding:10px;border-radius:10px}.kv small{display:block;color:var(--muted);margin-bottom:4px}.intel{margin-top:12px;padding:13px;border:1px solid var(--line);border-radius:11px}.state{font-size:11px;font-weight:800}.AVAILABLE{color:var(--accent)}.NOT_FOUND{color:var(--warn)}.NOT_CONFIGURED,.FAILED{color:var(--muted)}.progress{height:7px;background:var(--line);border-radius:99px;overflow:hidden;margin-top:8px}.progress i{display:block;height:100%;width:0;background:var(--accent);transition:.35s}.loading,.empty,.error{text-align:center;padding:32px;color:var(--muted)}.error{color:var(--danger)}.chart{display:grid;gap:10px;margin-top:14px}.barrow{display:grid;grid-template-columns:120px 1fr 35px;gap:8px;align-items:center}.bar{height:9px;background:var(--line);border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:var(--blue)}.bottom{display:none}.themepick button.on{background:var(--accent);color:#fff;border-color:var(--accent)}
@media(max-width:850px){.app{padding:12px 14px 85px}.nav{display:none}.bottom{display:grid;grid-template-columns:repeat(5,1fr);position:fixed;bottom:0;left:0;right:0;z-index:9;background:var(--card);border-top:1px solid var(--line);padding:6px}.bottom button{border:0;background:transparent;color:var(--muted);padding:8px 2px;font-size:10px}.bottom button.active{color:var(--accent);font-weight:800}.metrics,.split,.form{grid-template-columns:1fr 1fr}.form .primary{grid-column:span 2}.detailgrid{grid-template-columns:1fr}}@media(max-width:540px){.metrics,.split,.form{grid-template-columns:1fr}.form .primary{grid-column:auto}.status{display:none}.title{font-size:25px}.tools .version{display:none}}
</style></head><body><div class="app">
<header class="top"><div class="brand"><div class="logo">🟢</div><div><b>LEADHUNTER</b><div class="sub">Local Business Intelligence</div></div></div><div class="tools"><span class="sub status" id="sys">● Checking systems</span><span class="sub version">v4.2</span><button class="btn" onclick="go('settings')">🎨 Theme</button><button class="btn" onclick="refreshAll()">↻ Refresh</button></div></header>
<nav class="nav"><button class="active" onclick="go('overview')">🏠 Overview</button><button onclick="go('find')">🔎 Find Leads</button><button onclick="go('leads')">📁 Leads</button><button onclick="go('analytics')">📊 Analytics</button><button onclick="go('outreach')">📣 Act</button><button onclick="go('settings')">⚙️ Settings</button></nav>
<section class="page active" id="overview"><div class="eyebrow">COMMAND CENTER</div><h1 class="title">LeadHunter Overview</h1><p class="lead">Find local businesses, research real digital gaps and turn qualified opportunities into services.</p><div class="grid metrics"><div class="card metric"><span>📁 DATASETS</span><strong id="mDatasets">—</strong></div><div class="card metric"><span>🏢 LEADS</span><strong id="mLeads">—</strong></div><div class="card metric"><span>🔬 RESEARCHED</span><strong id="mResearch">—</strong></div><div class="card metric"><span>🎯 READY</span><strong id="mReady">—</strong></div></div><div class="grid split"><div class="card"><div class="row"><b>Recent datasets</b><button class="btn small" onclick="go('leads')">Open Leads</button></div><div class="list" id="recent"></div></div><div class="card"><b>System status</b><div class="list" id="services" style="margin-top:12px"></div></div></div></section>
<section class="page" id="find"><div class="eyebrow">DISCOVERY</div><h1 class="title">Find new leads.</h1><p class="lead">Choose a business type and city. Existing completed datasets are reused; refresh explicitly reruns discovery.</p><div class="card"><div class="form"><div class="field"><label>Business Type</label><select id="businessType"><option value="">Choose business type</option><option value="dental">🦷 Dental / Dentist</option><option value="hospital">🏥 Hospital</option><option value="clinic">🩺 Clinic</option><option value="restaurant">🍽️ Restaurant</option><option value="cafe">☕ Cafe</option><option value="bakery">🥐 Bakery</option><option value="hotel">🏨 Hotel</option><option value="resort">🌴 Resort</option><option value="school">🎓 School</option><option value="college">🏫 College</option><option value="university">🎓 University</option><option value="pharmacy">💊 Pharmacy</option><option value="gym">🏋️ Gym / Fitness</option><option value="salon">💇 Salon</option><option value="beauty">💄 Beauty</option><option value="car dealer">🚗 Car Dealer</option><option value="car repair">🔧 Car Repair</option><option value="car wash">🚿 Car Wash</option><option value="real estate">🏠 Real Estate</option><option value="lawyer">⚖️ Lawyer</option><option value="accountant">🧾 Accountant</option><option value="travel agency">✈️ Travel Agency</option><option value="electronics">📱 Electronics</option><option value="clothing">👕 Clothing</option><option value="furniture">🛋️ Furniture</option><option value="jewellery">💎 Jewellery</option><option value="supermarket">🛒 Supermarket</option><option value="hardware">🔨 Hardware</option><option value="bank">🏦 Bank</option><option value="insurance">🛡️ Insurance</option><option value="architect">🏛️ Architect</option><option value="construction">🏗️ Construction</option><option value="printing">🖨️ Printing</option><option value="photographer">📸 Photographer</option><option value="fuel">⛽ Fuel Station</option><option value="veterinary">🐾 Veterinary</option></select></div><div class="field"><label>City</label><select id="city"><option value="">Choose city</option><option>Bhopal</option><option>Indore</option><option>Jabalpur</option><option>Gwalior</option><option>Ujjain</option><option>Sagar</option><option>Rewa</option><option>Satna</option><option>Dewas</option><option>Ratlam</option><option>Burhanpur</option><option>Khandwa</option><option>Chhindwara</option><option>Vidisha</option><option>Shivpuri</option><option>Morena</option><option>Singrauli</option><option>Damoh</option><option>Mandsaur</option><option>Neemuch</option><option>Sehore</option><option>Betul</option><option>Itarsi</option><option>Narmadapuram</option><option>Khargone</option><option>Barwani</option><option>Dhar</option><option>Datia</option><option>Bhind</option><option>Balaghat</option><option>Chhatarpur</option><option>Tikamgarh</option><option>Panna</option><option>Raisen</option><option>Rajgarh</option><option>Shajapur</option><option>Agar Malwa</option><option>Alirajpur</option><option>Anuppur</option><option>Ashoknagar</option><option>Dindori</option><option>Harda</option><option>Jhabua</option><option>Katni</option><option>Mandla</option><option>Narsinghpur</option><option>Sheopur</option><option>Sidhi</option><option>Umaria</option></select></div><div class="field"><label>Lead Count</label><select id="leadCount"><option value="10">10</option><option value="20" selected>20</option><option value="30">30</option><option value="50">50</option></select></div><button class="btn primary" onclick="startDiscovery()">🔎 Find Leads</button></div><div id="discoveryState" class="sub" style="margin-top:14px"></div><div id="jobBox" style="display:none;margin-top:12px"><div class="row"><span id="jobText">Starting…</span><b id="jobPct">0%</b></div><div class="progress"><i id="jobBar"></i></div></div></div></section>
<section class="page" id="leads"><div class="eyebrow">LEAD DATABASE</div><h1 class="title">Your datasets.</h1><p class="lead">Click a dataset to load every lead inside it. There is no separate saved-search history page.</p><div class="list" id="datasets"></div><div id="leadTitle" class="row" style="margin-top:22px"></div><div class="list" id="leadList"></div></section>
<section class="page" id="analytics"><div class="eyebrow">INTELLIGENCE</div><h1 class="title">Analytics</h1><div class="grid metrics"><div class="card metric"><span>LEADS</span><strong id="aLeads">—</strong></div><div class="card metric"><span>HOT</span><strong id="aHot">—</strong></div><div class="card metric"><span>QUALIFIED</span><strong id="aQualified">—</strong></div><div class="card metric"><span>CONTACTED</span><strong id="aContacted">—</strong></div></div><div class="grid split"><div class="card"><b>📍 Cities</b><div class="chart" id="cityChart"></div></div><div class="card"><b>🎯 Services to sell</b><div id="serviceChart" class="chart"></div></div></div></section>
<section class="page" id="outreach"><div class="eyebrow">ACT</div><h1 class="title">Work opportunities.</h1><p class="lead">Deals and due follow-ups come from the real outreach API. Use a lead card to generate a pitch or save outreach.</p><div class="list" id="outreachList"></div></section>
<section class="page" id="settings"><div class="eyebrow">SETTINGS</div><h1 class="title">Appearance</h1><div class="card"><b>Choose a complete dashboard theme</b><p class="lead">Modern and Neo are separate visual styles. Your choice is saved in this browser.</p><div class="themepick"><button class="btn" data-theme="light-modern" onclick="setTheme('light','modern',this)">☀️ Light Modern</button><button class="btn" data-theme="dark-modern" onclick="setTheme('dark','modern',this)">🌙 Dark Modern</button><button class="btn" data-theme="light-neo" onclick="setTheme('light','neo',this)">✨ Light Neo</button><button class="btn" data-theme="dark-neo" onclick="setTheme('dark','neo',this)">🖤 Dark Neo</button></div></div><div class="card" style="margin-top:16px"><b>What's new · v4.2</b><div class="sub" style="margin-top:8px">• Verified dataset endpoint wiring<br>• Dropdown-based discovery<br>• Dataset click loads real leads<br>• Real Research / Pitch / Outreach actions<br>• Explicit intelligence availability states<br>• Four persistent themes</div></div></section>
</div><nav class="bottom"><button class="active" onclick="go('overview')">🏠<br>Home</button><button onclick="go('find')">🔎<br>Find</button><button onclick="go('leads')">📁<br>Leads</button><button onclick="go('analytics')">📊<br>Data</button><button onclick="go('outreach')">📣<br>Act</button></nav><div id="toast" style="display:none;position:fixed;right:18px;bottom:70px;background:#18212f;color:#fff;padding:12px 16px;border-radius:10px;z-index:20"></div>
<script>
const $=x=>document.getElementById(x);let active='overview',selectedDataset=null,toastTimer;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,opt={}){let r=await fetch('/api'+path,opt),j={};try{j=await r.json()}catch{}if(!r.ok)throw Error(j.detail||'Request failed');return j}
function say(t){clearTimeout(toastTimer);$('toast').textContent=t;$('toast').style.display='block';toastTimer=setTimeout(()=>$('toast').style.display='none',2800)}
function go(id){active=id;document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===id));document.querySelectorAll('.nav button,.bottom button').forEach(b=>b.classList.toggle('active',b.getAttribute('onclick')==="go('"+id+"')"));if(id==='overview')loadOverview();if(id==='leads')loadDatasets();if(id==='analytics')loadAnalytics();if(id==='outreach')loadOutreach();scrollTo({top:0,behavior:'smooth'})}
function loading(id,t='Loading…'){$(id).innerHTML='<div class="loading">'+t+'</div>'}
function error(id,e){$(id).innerHTML='<div class="error">⚠️ '+esc(e.message||e)+'</div>'}
async function loadOverview(){try{let x=await api('/overview'),m=x.metrics||{};$('mDatasets').textContent=m.datasets??0;$('mLeads').textContent=m.leads??0;$('mResearch').textContent=m.researched??0;$('mReady').textContent=m.ready??0;$('recent').innerHTML=(x.recent||[]).map(d=>'<div class="item dataset" onclick="openDataset('+d.id+')"><b>'+esc(d.industry)+' · '+esc(d.city)+'</b><div class="sub">'+(d.result_count||0)+' leads · '+esc(d.status||'UNKNOWN')+'</div></div>').join('')||'<div class="empty">No datasets yet. Find your first leads.</div>';let s=await fetch('/system/status').then(r=>r.json());let sv=s.services||{};$('sys').textContent='● '+(Object.values(sv).some(v=>v)?'SYSTEM LIVE':'CHECK SYSTEM');$('services').innerHTML=Object.entries(sv).map(([k,v])=>'<div class="item">'+(v?'🟢':'⚪')+' '+esc(k.replace('_',' '))+'</div>').join('')}catch(e){error('recent',e)}}
async function startDiscovery(){let category=$('businessType').value,city=$('city').value,max_results=+$('leadCount').value;if(!category||!city)return say('Choose a business type and city');$('discoveryState').textContent='Starting '+category+' discovery in '+city+'…';$('jobBox').style.display='block';$('jobBar').style.width='5%';try{let x=await api('/discover',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({category,city,max_results,refresh:false})});if(x.reused){$('discoveryState').textContent='Existing '+category+' · '+city+' dataset loaded — no duplicate created.';$('jobBox').style.display='none';go('leads');setTimeout(()=>openDataset(x.dataset_id),150);return}pollJob(x.job_id,category,city)}catch(e){$('discoveryState').textContent='⚠️ '+e.message;$('jobBox').style.display='none'}}
async function pollJob(id,category,city){try{let x=await api('/jobs/'+id),p=x.progress||0,it=x.item||{};$('jobPct').textContent=p+'%';$('jobBar').style.width=p+'%';$('jobText').textContent=(x.businesses_found||0)+' businesses processed';if(it.status==='DONE'){say('Discovery complete');$('discoveryState').textContent='Done. Opening '+category+' · '+city+' leads.';$('jobBox').style.display='none';go('leads');setTimeout(()=>openDataset(id),150);return}if(it.status==='FAILED'){throw Error(it.error||'Discovery failed')}setTimeout(()=>pollJob(id,category,city),1200)}catch(e){$('jobText').textContent='⚠️ '+e.message}}
async function loadDatasets(){loading('datasets','Loading datasets…');try{let x=await api('/datasets'),items=x.items||[];$('datasets').innerHTML=items.map(d=>'<div class="item dataset '+(selectedDataset===d.id?'selected':'')+'" onclick="openDataset('+d.id+')"><div class="row"><div><b>📁 '+esc(d.industry)+' · '+esc(d.city)+'</b><div class="sub">'+(d.result_count||0)+' leads · '+esc(d.status||'UNKNOWN')+'</div></div><span>›</span></div></div>').join('')||'<div class="empty">No datasets yet. Use Find Leads to create one.</div>'}catch(e){error('datasets',e)}}
async function openDataset(id){selectedDataset=id;loading('leadList','Loading dataset leads…');$('leadTitle').innerHTML='<b>Loading leads…</b>';try{let x=await api('/datasets/'+id+'/leads'),items=x.items||[];$('leadTitle').innerHTML='<b>'+items.length+' leads in this dataset</b><span class="sub">Click a card to expand</span>';$('leadList').innerHTML=items.map(leadCard).join('')||'<div class="empty">This dataset has no leads.</div>';loadDatasets()}catch(e){error('leadList',e)}}
function leadCard(l){let services=(l.recommended_services||[]).map(x=>'<span class="tag">'+esc(x)+'</span>').join('');let r=l.research||{},web=r.website||{},google=r.google||{},search=r.search||{};return '<div class="card leadcard" id="lead-'+l.id+'"><div class="leadhead" onclick="toggleLead('+l.id+')"><div><b>🏢 '+esc(l.name)+'</b><div class="sub">'+esc(l.industry||'Business')+' · '+esc(l.city||'Unknown city')+'</div></div><div><b style="color:var(--warn)">'+(l.score??'—')+'</b> ›</div></div><div class="details"><div class="detailgrid"><div class="kv"><small>📞 PHONE</small>'+esc(l.phone||'Not available')+'</div><div class="kv"><small>✉️ EMAIL</small>'+esc(l.email||'Not available')+'</div><div class="kv"><small>🌐 WEBSITE</small>'+esc(l.website||'Not available')+'</div><div class="kv"><small>📍 ADDRESS</small>'+esc(l.address||'Not available')+'</div></div><div class="intel"><b>🔎 GOOGLE & MAPS INTELLIGENCE</b><div class="sub">Profile: <span class="state '+esc(google.status||'NOT_FOUND')+'">'+esc(google.status||'NOT_FOUND')+'</span> · Rating: '+esc(google.rating??'Not available')+' · Reviews: '+esc(google.review_count??'Not available')+'</div><div class="sub">Website: <span class="state '+esc(web.status||'NOT_FOUND')+'">'+esc(web.status||'NOT_FOUND')+'</span> · Search: <span class="state '+esc(search.status||'NOT_CONFIGURED')+'">'+esc(search.status||'NOT_CONFIGURED')+'</span></div></div><div class="intel"><b>💡 OPPORTUNITIES</b><div>'+(services||'<span class="sub">Research this lead for recommendations.</span>')+'</div></div><div class="actions"><button class="btn small primary" onclick="event.stopPropagation();researchLead('+l.id+')">🔬 Research</button><button class="btn small" onclick="event.stopPropagation();pitchLead('+l.id+')">✨ Generate Pitch</button><button class="btn small" onclick="event.stopPropagation();saveOutreach('+l.id+')">📣 Add to Act</button></div><div id="result-'+l.id+'" class="sub" style="margin-top:10px"></div></div></div>'}
function toggleLead(id){$('lead-'+id).classList.toggle('open')}
async function researchLead(id){let el=$('result-'+id);el.textContent='🔬 Researching…';try{let x=await api('/leads/'+id+'/research',{method:'POST'});el.textContent='🟢 Research complete · Score '+(x.score?.score??'—');say('Research saved.');if(selectedDataset)openDataset(selectedDataset)}catch(e){el.textContent='⚠️ '+e.message}}
async function pitchLead(id){let el=$('result-'+id);el.textContent='✨ Generating pitch…';try{let x=await api('/leads/'+id+'/pitch',{method:'POST'});el.textContent=x.pitch||'Pitch generated';say('Pitch generated.')}catch(e){el.textContent='⚠️ '+e.message}}
async function saveOutreach(id){try{await api('/outreach/'+id,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({stage:'READY',notes:'Added from dashboard',services:[]})});say('Added to Act.');if(active==='outreach')loadOutreach()}catch(e){say('⚠️ '+e.message)}}
async function loadAnalytics(){try{let x=await api('/analytics'),t=x.totals||{};$('aLeads').textContent=t.leads??0;$('aHot').textContent=t.hot??0;$('aQualified').textContent=t.qualified??0;$('aContacted').textContent=t.contacted??0;bars('cityChart',x.cities||[]);bars('serviceChart',x.services||[])}catch(e){error('cityChart',e);error('serviceChart',e)}}
function bars(id,items){let max=Math.max(1,...items.map(x=>x.count||0));$(id).innerHTML=items.length?items.map(x=>'<div class="barrow"><span class="sub">'+esc(x.name)+'</span><div class="bar"><i style="width:'+(x.count/max*100)+'%"></i></div><b>'+x.count+'</b></div>').join(''):'<div class="empty">No data yet.</div>'}
async function loadOutreach(){loading('outreachList','Loading deals and follow-ups…');try{let x=await api('/outreach'),items=x.items||[],follow=x.followups||[];let html='';if(items.length)html+='<div class="sub">ACTIVE DEALS</div>'+items.map(i=>'<div class="item"><b>📣 '+esc(i.business_name)+'</b><div class="sub">'+esc(i.stage||'READY')+' · '+(i.services||[]).map(esc).join(', ')+'</div></div>').join('');if(follow.length)html+='<div class="sub" style="margin-top:12px">DUE FOLLOW-UPS</div>'+follow.map(i=>'<div class="item"><b>⏰ '+esc(i.business_name)+'</b><div class="sub">'+esc(i.notes||'Follow up')+'</div></div>').join('');$('outreachList').innerHTML=html||'<div class="empty">No outreach items yet. Add a lead from the Leads page.</div>'}catch(e){error('outreachList',e)}}
function setTheme(mode,style,btn){document.body.classList.toggle('dark',mode==='dark');document.body.classList.toggle('neo',style==='neo');localStorage.setItem('lh-theme',mode+'-'+style);document.querySelectorAll('[data-theme]').forEach(b=>b.classList.toggle('on',b===btn))}
function restoreTheme(){let v=localStorage.getItem('lh-theme')||'light-modern',[m,s]=v.split('-');let b=document.querySelector('[data-theme="'+v+'"]');setTheme(m,s,b)}
function refreshAll(){loadOverview();if(active==='leads')loadDatasets();if(active==='analytics')loadAnalytics();if(active==='outreach')loadOutreach();say('Dashboard refreshed')}
restoreTheme();loadOverview();
</script></body></html>"""
